package campfire.rails;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import at.favre.lib.crypto.bcrypt.BCrypt;
import io.vertx.core.json.Json;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Test;

/// Golden vectors generated by the Rails reference app (`vectors/rails_compat.json`).
class RailsCompatTest {
    @SuppressWarnings("unchecked")
    static final Map<String, Object> V = (Map<String, Object>) load("/vectors/rails_compat.json");
    static final Secrets SECRETS = new Secrets((String) V.get("secret_key_base"));

    static Object load(String path) {
        try (var in = RailsCompatTest.class.getResourceAsStream(path)) {
            return Json.decodeValue(new String(in.readAllBytes(), StandardCharsets.UTF_8), Map.class);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    @SuppressWarnings("unchecked")
    static List<Map<String, Object>> cases(String section, String kind) {
        Object s = V.get(section);
        return (List<Map<String, Object>>) (kind == null ? s : ((Map<String, Object>) s).get(kind));
    }

    /// Formats Rails still reads but no Campfire install wrote, which this app rejects: values
    /// signed without a purpose (Rails before 5.2) and globalid < 1.0's self-validated sgids.
    static final Set<String> UNWRITTEN_FORMATS = Set.of("no metadata (pre-5.2), any name", "no metadata under another name",
        "metadata without purpose", "no metadata (any name)", "self-validated metadata (globalid < 1.0)",
        "self-validated metadata, not yet expired");

    static Object expected(Map<String, Object> c) {
        return UNWRITTEN_FORMATS.contains(c.get("case")) ? null : c.get("expected");
    }

    static Instant time(Object value) {
        return value == null ? null : Instant.parse((String) value);
    }

    @Test
    void keyGenerator() {
        for (var c : cases("key_generator", null)) {
            byte[] key = SECRETS.keyGenerator().generateKey((String) c.get("salt"), ((Number) c.get("length")).intValue());
            assertEquals(c.get("key_hex"), HexFormat.of().formatHex(key), (String) c.get("salt"));
        }
    }

    @Test
    void cookieEscaping() {
        for (var c : cases("cookie_escaping", null)) {
            if (c.get("raw") != null) assertEquals(c.get("wire"), HttpFormats.escape((String) c.get("raw")));
            assertEquals(c.get("parsed"), HttpFormats.unescape((String) c.get("wire")));
        }
    }

    @Test
    void signedCookies() {
        for (var c : cases("signed_cookies", "generate")) {
            if (!(c.get("value") instanceof String value)) continue;
            String name = (String) c.get("name");
            String signed = SECRETS.signCookie(name, value, time(c.get("expires_at")));
            if (signed.equals(c.get("raw"))) continue;
            // `ActiveSupport::JSON` escapes `<`, `>` and `&` and Vert.x doesn't, so those signatures
            // differ; Rails checks the signature over the bytes and reads either JSON.
            assertTrue(value.matches("(?s).*[<>&].*"), (String) c.get("case"));
            Instant now = c.get("expires_at") == null ? Instant.now() : time(c.get("expires_at")).minusSeconds(1);
            assertEquals(value, SECRETS.verifySignedCookie(name, signed, now), (String) c.get("case"));
        }
        for (var c : cases("signed_cookies", "verify")) {
            Object expected = expected(c);
            String actual = SECRETS.verifySignedCookie((String) c.get("name"), (String) c.get("raw"), time(c.get("now")));
            if (expected == null || expected instanceof String) assertEquals(expected, actual, (String) c.get("case"));
        }
    }

    @Test
    void encryptedCookies() {
        for (var c : cases("encrypted_cookies", "verify")) {
            Object actual = SECRETS.decryptCookie((String) c.get("name"), (String) c.get("raw"), time(c.get("now")));
            assertEquals(expected(c), actual, (String) c.get("case"));
        }
        String raw = SECRETS.encryptCookie("_campfire_session", Map.of("a", "b"), null);
        assertEquals(Map.of("a", "b"), SECRETS.decryptCookie("_campfire_session", raw, Instant.now()));
    }

    @Test
    void signedIds() {
        for (var c : cases("signed_ids", "generate")) {
            assertEquals(c.get("signed_id"), SECRETS.signedId((String) c.get("model"), ((Number) c.get("id")).longValue(), (String) c.get("purpose"),
                time(c.get("expires_at"))));
        }
        for (var c : cases("signed_ids", "verify")) {
            assertEquals(String.valueOf(c.get("expected")), String.valueOf(SECRETS.verifySignedId((String) c.get("model"), (String) c.get("signed_id"),
                (String) c.get("purpose"), time(c.get("now")))), (String) c.get("case"));
        }
    }

    @Test
    void globalIds() {
        for (var c : cases("global_ids", null)) {
            var gid = GlobalId.of((String) c.get("model_name"), c.get("id"));
            assertEquals(c.get("gid"), gid.toString());
            assertEquals(c.get("param"), gid.toParam());
            assertEquals(gid, GlobalId.fromParam((String) c.get("param")));
        }
    }

    @Test
    void sgids() {
        for (var c : cases("sgids", "generate")) {
            var gid = GlobalId.parse((String) c.get("gid"));
            String expected = (String) c.get("sgid");
            if (((String) c.get("data")).endsWith("?expires_in") && "attachable".equals(c.get("purpose"))) {
                assertEquals(expected, SECRETS.attachableSgid(gid));
            } else {
                assertEquals(expected, SECRETS.sgid(gid, (String) c.get("purpose"), time(c.get("expires_at"))));
            }
        }
        for (var c : cases("sgids", "verify")) {
            GlobalId located = SECRETS.locateSigned((String) c.get("sgid"), (String) c.get("purpose"), time(c.get("now")));
            Object expected = expected(c);
            String expectedGid = expected == null ? null : GlobalId.parse((String) expected).toString();
            assertEquals(expectedGid, located == null ? null : located.toString(), (String) c.get("case"));
        }
    }

    @Test
    void turboStreamNames() {
        for (var c : cases("turbo_stream_names", "generate")) {
            @SuppressWarnings("unchecked")
            var parts = ((List<String>) c.get("parts")).toArray(String[]::new);
            assertEquals(c.get("signed"), SECRETS.signedStreamName(parts));
        }
        for (var c : cases("turbo_stream_names", "verify")) {
            Object e = c.get("expected");
            assertEquals(e == null ? null : e.toString(), SECRETS.verifiedStreamName((String) c.get("signed")), (String) c.get("case"));
        }
    }

    @Test
    void appVerifiers() {
        for (var c : cases("app_verifiers", "generate")) {
            var verifier = SECRETS.appVerifier((String) c.get("name"));
            assertEquals(c.get("message"), verifier.generateRaw((String) c.get("data_json"), (String) c.get("purpose"), time(c.get("expires_at"))));
        }
        for (var c : cases("app_verifiers", "verify")) {
            var verifier = SECRETS.appVerifier((String) c.get("name"));
            Object value = verifier.verified((String) c.get("message"), (String) c.get("purpose"), time(c.get("now")));
            Object expected = c.get("expected_json") == null ? null : plain(Json.decodeValue((String) c.get("expected_json")));
            assertEquals(expected, value, (String) c.get("case"));
        }
    }

    @Test
    void passwords() {
        for (var c : cases("passwords", "checks")) {
            byte[] password = ((String) c.get("password")).getBytes(StandardCharsets.UTF_8);
            if (password.length > 72) password = java.util.Arrays.copyOf(password, 72);
            boolean verified;
            try {
                verified = BCrypt.verifyer().verify(password, ((String) c.get("digest")).getBytes(StandardCharsets.UTF_8)).verified;
            } catch (RuntimeException e) {
                verified = false;
            }
            assertEquals(c.get("expected"), verified, c.toString());
        }
    }

    /// What the verifiers return: plain `Map`s and `List`s.
    private static Object plain(Object value) {
        return value instanceof JsonObject o ? o.getMap() : value instanceof JsonArray a ? a.getList() : value;
    }
}
